def areTheySimilar(mat, k):
    m = len(mat)
    n = len(mat[0])

    for i in range(m):
        moves = k % n
        # For even-indexed row: left shift
        if i % 2 == 0:
            shifted_row = mat[i][moves:] + mat[i][:moves]
        # For odd-indexed row: right shift
        else:
            shifted_row = mat[i][-moves:] + mat[i][:-moves]
        if shifted_row != mat[i]:
            return False
    return True
